#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum AuthAuditKind {
    LoginSuccess,
    LoginFailure,
    Logout,
    PasswordChanged,
    PasswordResetRequested,
    PasswordResetCompleted,
    MagicLinkRequested,
    MagicLinkConsumed,
    MagicLinkRejected,
    OidcLoginStarted,
    OidcLoginCompleted,
    OidcLoginRejected,
    TotpChallengeCreated,
    TotpVerificationSuccess,
    TotpVerificationFailure,
    RecoveryCodesGenerated,
    RecoveryCodeConsumed,
    RecoveryCodeRejected,
    PasskeyRegistrationStarted,
    PasskeyRegistrationCompleted,
    PasskeyRegistrationFailed,
    PasskeyLoginStarted,
    PasskeyLoginCompleted,
    PasskeyLoginFailed,
    LdapLoginSuccess,
    LdapLoginFailure,
    ApiTokenCreated,
    ApiTokenRevoked,
    SessionCreated,
    SessionRotated,
    SessionExpired,
    SessionRevoked,
    AccountLocked,
    AccountUnlocked,
    RateLimitExceeded,
    BruteForceDetected,
    AuthMethodDisabled,
    PolicyViolation,
    TrustedProxyAccepted,
    TrustedProxyRejected,
}

impl AuthAuditKind {
    pub fn as_str(self) -> &'static str {
        match self {
            Self::LoginSuccess => "login_success",
            Self::LoginFailure => "login_failure",
            Self::Logout => "logout",
            Self::PasswordChanged => "password_changed",
            Self::PasswordResetRequested => "password_reset_requested",
            Self::PasswordResetCompleted => "password_reset_completed",
            Self::MagicLinkRequested => "magic_link_requested",
            Self::MagicLinkConsumed => "magic_link_consumed",
            Self::MagicLinkRejected => "magic_link_rejected",
            Self::OidcLoginStarted => "oidc_login_started",
            Self::OidcLoginCompleted => "oidc_login_completed",
            Self::OidcLoginRejected => "oidc_login_rejected",
            Self::TotpChallengeCreated => "totp_challenge_created",
            Self::TotpVerificationSuccess => "totp_verification_success",
            Self::TotpVerificationFailure => "totp_verification_failure",
            Self::RecoveryCodesGenerated => "recovery_codes_generated",
            Self::RecoveryCodeConsumed => "recovery_code_consumed",
            Self::RecoveryCodeRejected => "recovery_code_rejected",
            Self::PasskeyRegistrationStarted => "passkey_registration_started",
            Self::PasskeyRegistrationCompleted => "passkey_registration_completed",
            Self::PasskeyRegistrationFailed => "passkey_registration_failed",
            Self::PasskeyLoginStarted => "passkey_login_started",
            Self::PasskeyLoginCompleted => "passkey_login_completed",
            Self::PasskeyLoginFailed => "passkey_login_failed",
            Self::LdapLoginSuccess => "ldap_login_success",
            Self::LdapLoginFailure => "ldap_login_failure",
            Self::ApiTokenCreated => "api_token_created",
            Self::ApiTokenRevoked => "api_token_revoked",
            Self::SessionCreated => "session_created",
            Self::SessionRotated => "session_rotated",
            Self::SessionExpired => "session_expired",
            Self::SessionRevoked => "session_revoked",
            Self::AccountLocked => "account_locked",
            Self::AccountUnlocked => "account_unlocked",
            Self::RateLimitExceeded => "rate_limit_exceeded",
            Self::BruteForceDetected => "brute_force_detected",
            Self::AuthMethodDisabled => "auth_method_disabled",
            Self::PolicyViolation => "policy_violation",
            Self::TrustedProxyAccepted => "trusted_proxy_accepted",
            Self::TrustedProxyRejected => "trusted_proxy_rejected",
        }
    }
}
